DECLARE @tempTaskProcessId AS UNIQUEIDENTIFIER, @tempTaskId AS UNIQUEIDENTIFIER, @tempTaskProcessTypeCode AS INT
SELECT @tempTaskProcessId= tp.TaskProcessId, @tempTaskId = t.TaskId FROM PFM_EXT_TaskProcess tp inner JOIN dbo.PFM_EXT_Task t ON tp.TaskProcessId = t.TaskProcessId
1
if @tempTaskProcessId is not null and @tempTaskId is not null begin
UPDATE PFM_EXT_TaskProcess
@tempTaskProcessId
UPDATE PFM_EXT_TaskProcessFields
@tempTaskProcessId
UPDATE PFM_EXT_Task
@tempTaskId
UPDATE PFM_EXT_TaskFields
@tempTaskId
end
